mapper.select:
select t.config_id configId,t.community_id communityId,t.evasion_open evasionOpen,
t.query_days queryDays,t.query_minutes queryMinutes,t.status_cd statusCd
from car_inout_evasion_config t
where 1=1
and t.status_cd = '0'

    and t.config_id= #{configId}


    and t.community_id= #{communityId}


    and t.evasion_open= #{evasionOpen}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update car_inout_evasion_config t set t.status_cd = #{statusCd}

    , t.evasion_open= #{evasionOpen}


    , t.query_days= #{queryDays}


    , t.query_minutes= #{queryMinutes}

where 1=1

    and t.config_id= #{configId}


    and t.community_id= #{communityId}
